package com.bank.resilience.client;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Simulates the downstream fraud-check service. Can be flipped "down".
public class FraudCheckClient {
    private static final Logger log = Logger.getLogger(FraudCheckClient.class.getName());
    private volatile boolean down = false;

    public void setDown(boolean down) { this.down = down; }

    // Returns a risk score 0..100. Throws if the service is down (timeout/error).
    public int score(String accountId, BigDecimal amount) {
        if (down) {
            log.severe(() -> "FRAUD-CHECK call failed for " + accountId + " (service down)");
            throw new RuntimeException("fraud-check unavailable");
        }
        int score = amount.compareTo(new BigDecimal("100000")) > 0 ? 70 : 10;
        log.fine(() -> "FRAUD-CHECK score for " + accountId + " = " + score);
        return score;
    }
}
