package com.bank.resilience.breaker;

import java.util.logging.Logger;

// Minimal circuit breaker illustrating CLOSED -> OPEN -> HALF_OPEN.
public class CircuitBreaker {
    private static final Logger log = Logger.getLogger(CircuitBreaker.class.getName());
    public enum State { CLOSED, OPEN, HALF_OPEN }

    private State state = State.CLOSED;
    private int consecutiveFailures = 0;
    private final int failureThreshold;
    private final long openDurationMillis;
    private long openedAt = 0;

    public CircuitBreaker(int failureThreshold, long openDurationMillis) {
        this.failureThreshold = failureThreshold;
        this.openDurationMillis = openDurationMillis;
    }

    public boolean allowRequest() {
        if (state == State.OPEN) {
            if (System.currentTimeMillis() - openedAt >= openDurationMillis) {
                state = State.HALF_OPEN;
                log.warning("CIRCUIT half-open: allowing trial call");
                return true;
            }
            return false; // fail fast
        }
        return true;
    }

    public void onSuccess() {
        consecutiveFailures = 0;
        if (state != State.CLOSED) log.info("CIRCUIT closed: dependency healthy again");
        state = State.CLOSED;
    }

    public void onFailure() {
        consecutiveFailures++;
        if (state == State.HALF_OPEN || consecutiveFailures >= failureThreshold) {
            state = State.OPEN;
            openedAt = System.currentTimeMillis();
            log.severe(() -> "CIRCUIT open: stop calling dependency (failures="
                    + consecutiveFailures + ")");
        }
    }

    public State getState() { return state; }
}
