package com.bank.resilience.service;

import com.bank.resilience.breaker.CircuitBreaker;
import com.bank.resilience.client.FraudCheckClient;
import com.bank.resilience.model.Account;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class ResilientTransferService {
    private static final Logger log = Logger.getLogger(ResilientTransferService.class.getName());
    private final FraudCheckClient fraudClient;
    private final CircuitBreaker breaker;
    private int fallbackCount = 0; // monitoring counter

    public ResilientTransferService(FraudCheckClient fraudClient, CircuitBreaker breaker) {
        this.fraudClient = fraudClient;
        this.breaker = breaker;
    }

    public void transfer(Account from, Account to, BigDecimal amount) {
        int riskScore = checkFraudResilient(from.getAccountId(), amount);
        if (riskScore >= 80) {
            log.warning(() -> "TRANSFER BLOCKED high risk score " + riskScore);
            return;
        }
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "TRANSFER " + amount + " from " + from.getAccountId()
                + " to " + to.getAccountId() + " SUCCESS (risk=" + riskScore + ")");
    }

    // Wraps the downstream call with circuit breaker, bounded retry, and fallback.
    private int checkFraudResilient(String accountId, BigDecimal amount) {
        if (!breaker.allowRequest()) {
            return fallbackScore(accountId, amount); // fail fast, degrade
        }
        int attempts = 0;
        long backoff = 200;
        while (attempts < 3) {
            attempts++;
            try {
                int score = fraudClient.score(accountId, amount);
                breaker.onSuccess();
                return score;
            } catch (RuntimeException ex) {
                breaker.onFailure();
                log.warning(() -> "Retry " + " after failure; backoff " + "ms");
                if (!breaker.allowRequest()) break; // breaker opened, stop retrying
                sleep(backoff);
                backoff *= 2; // exponential backoff
            }
        }
        return fallbackScore(accountId, amount);
    }

    // Graceful degradation: conservative default + flag for manual review.
    private int fallbackScore(String accountId, BigDecimal amount) {
        fallbackCount++;
        int provisional = amount.compareTo(new BigDecimal("100000")) > 0 ? 85 : 30;
        log.warning(() -> "FALLBACK provisional risk=" + provisional + " for " + accountId
                + " (flagged for manual review)");
        return provisional;
    }

    public int getFallbackCount() { return fallbackCount; }
    public CircuitBreaker.State breakerState() { return breaker.getState(); }

    private void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
