package com.bank.resilience;

import com.bank.resilience.breaker.CircuitBreaker;
import com.bank.resilience.client.FraudCheckClient;
import com.bank.resilience.model.Account;
import com.bank.resilience.service.ResilientTransferService;
import java.math.BigDecimal;
import java.util.logging.*;

public class ResilienceDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        FraudCheckClient fraud = new FraudCheckClient();
        CircuitBreaker breaker = new CircuitBreaker(3, 10000);
        ResilientTransferService service = new ResilientTransferService(fraud, breaker);

        // Healthy: fraud-check works, transfers succeed normally.
        service.transfer(rajesh, priya, new BigDecimal("50000"));

        // Fraud-check goes DOWN.
        Logger.getLogger(ResilienceDemo.class.getName())
              .severe("Fraud-check service is now DOWN");
        fraud.setDown(true);

        // These transfers: retries exhaust, breaker opens, fallback serves.
        for (int i = 0; i < 5; i++) {
            service.transfer(rajesh, priya, new BigDecimal("50000"));
        }

        Logger.getLogger(ResilienceDemo.class.getName())
              .info("Breaker state=" + service.breakerState()
                    + ", fallback invocations=" + service.getFallbackCount());
    }
}

